      if (IsContest())
          gTasks[taskId].tBackgroundId = bg3;
      else if (GetBattlerSide(gBattleAnimTarget) == B_SIDE_PLAYER)
          gTasks[taskId].tBackgroundId = bg2;
      else
          gTasks[taskId].tBackgroundId = bg1;

      sAnimBackgroundFadeState = 1;
