/** static void Task_FadeToBg(u8 taskId) */
export function Task_FadeToBg(taskId: any): any {
  if (gTasks[taskId].tState == 0)
      {
          BeginHardwarePaletteFade(0xE8, 0, 0, 16, 0);
          gTasks[taskId].tState++;
          return;
      }
      if (gPaletteFade.active)
          return;
      if (gTasks[taskId].tState == 1)
      {
          gTasks[taskId].tState++;
          sAnimBackgroundFadeState = 2;
      }
      else if (gTasks[taskId].tState == 2)
      {
          let bgId: any = gTasks[taskId].tBackgroundId;

          if (bgId == -1)
              LoadDefaultBg();
          else
              LoadMoveBg(bgId);

          BeginHardwarePaletteFade(0xE8, 0, 16, 0, 1);
          gTasks[taskId].tState++;
          return;
      }
      if (gPaletteFade.active)
          return;
      if (gTasks[taskId].tState == 3)
      {
          DestroyTask(taskId);
          sAnimBackgroundFadeState = 0;
      }
}

/** static void LoadMoveBg(u16 bgId) */
export function LoadMoveBg(bgId: any): any {
  if (IsContest())
      {
          let tilemap: any = gBattleAnimBackgroundTable[bgId].tilemap;
          let dmaSrc: any = null;
          let dmaDest: any = null;

          LZDecompressWram(tilemap, gDecompressionBuffer);
          RelocateBattleBgPal(GetBattleBgPaletteNum(), gDecompressionBuffer, 0x100, FALSE);
          dmaSrc = gDecompressionBuffer;
          dmaDest = BG_SCREEN_ADDR(26);
          DmaCopy32(3, dmaSrc, dmaDest, 0x800);
          LZDecompressVram(gBattleAnimBackgroundTable[bgId].image, BG_SCREEN_ADDR(4));
          LoadCompressedPalette(gBattleAnimBackgroundTable[bgId].palette, BG_PLTT_ID(GetBattleBgPaletteNum()), PLTT_SIZE_4BPP);
      }
      else
      {
          LZDecompressVram(gBattleAnimBackgroundTable[bgId].tilemap, BG_SCREEN_ADDR(26));
          LZDecompressVram(gBattleAnimBackgroundTable[bgId].image, BG_CHAR_ADDR(2));
          LoadCompressedPalette(gBattleAnimBackgroundTable[bgId].palette, BG_PLTT_ID(2), PLTT_SIZE_4BPP);
      }
}

/** static void LoadDefaultBg(void) */
export function LoadDefaultBg(): any {
  if (IsContest())
          LoadContestBgAfterMoveAnim();
      else
          DrawMainBattleBackground();
}

