/** static void Cmd_jumpifcontest(void) */
export function Cmd_jumpifcontest(): any {
  sBattleAnimScriptPtr++;
      if (IsContest())
          sBattleAnimScriptPtr = T2_READ_PTR(sBattleAnimScriptPtr);
      else
          sBattleAnimScriptPtr += 4;
}

/** static void Cmd_splitbgprio(void) */
export function Cmd_splitbgprio(): any {
  let wantedBattler: any = null;
      let battler: any = null;
      let battlerPosition: any = null;

      wantedBattler = sBattleAnimScriptPtr[1];
      sBattleAnimScriptPtr += 2;

      if (wantedBattler != ANIM_ATTACKER)
          battler = gBattleAnimTarget;
      else
          battler = gBattleAnimAttacker;

       
      battlerPosition = GetBattlerPosition(battler);
      if (!IsContest() && (battlerPosition == B_POSITION_PLAYER_LEFT || battlerPosition == B_POSITION_OPPONENT_RIGHT))
      {
          SetAnimBgAttribute(1, BG_ANIM_PRIORITY, 1);
          SetAnimBgAttribute(2, BG_ANIM_PRIORITY, 2);
      }
}

/** static void Cmd_splitbgprio_all(void) */
export function Cmd_splitbgprio_all(): any {
  sBattleAnimScriptPtr++;
      if (!IsContest())
      {
          SetAnimBgAttribute(1, BG_ANIM_PRIORITY, 1);
          SetAnimBgAttribute(2, BG_ANIM_PRIORITY, 2);
      }
}

/** static void Cmd_splitbgprio_foes(void) */
export function Cmd_splitbgprio_foes(): any {
  let wantedBattler: any = null;
      let battlerPosition: any = null;
      let battler: any = null;

      wantedBattler = sBattleAnimScriptPtr[1];
      sBattleAnimScriptPtr += 2;

       
      if (GetBattlerSide(gBattleAnimAttacker) != GetBattlerSide(gBattleAnimTarget))
      {
          if (wantedBattler != ANIM_ATTACKER)
              battler = gBattleAnimTarget;
          else
              battler = gBattleAnimAttacker;

           
          battlerPosition = GetBattlerPosition(battler);
          if (!IsContest() && (battlerPosition == B_POSITION_PLAYER_LEFT || battlerPosition == B_POSITION_OPPONENT_RIGHT))
          {
              SetAnimBgAttribute(1, BG_ANIM_PRIORITY, 1);
              SetAnimBgAttribute(2, BG_ANIM_PRIORITY, 2);
          }
      }
}

/** static void Cmd_invisible(void) */
export function Cmd_invisible(): any {
  let spriteId: any = null;

      spriteId = GetAnimBattlerSpriteId(sBattleAnimScriptPtr[1]);
      if (spriteId != SPRITE_NONE)
          gSprites[spriteId].invisible = TRUE;

      sBattleAnimScriptPtr += 2;
}

/** static void Cmd_visible(void) */
export function Cmd_visible(): any {
  let spriteId: any = null;

      spriteId = GetAnimBattlerSpriteId(sBattleAnimScriptPtr[1]);
      if (spriteId != SPRITE_NONE)
          gSprites[spriteId].invisible = FALSE;

      sBattleAnimScriptPtr += 2;
}

/** static void Cmd_teamattack_moveback(void) */
export function Cmd_teamattack_moveback(): any {
  let wantedBattler: any = null;
      let priorityRank: any = null;
      let spriteId: any = null;

      wantedBattler = sBattleAnimScriptPtr[1];
      sBattleAnimScriptPtr += 2;

       
      if (!IsContest() && IsDoubleBattle()
       && GetBattlerSide(gBattleAnimAttacker) == GetBattlerSide(gBattleAnimTarget))
      {
          if (wantedBattler == ANIM_ATTACKER)
          {
              priorityRank = GetBattlerSpriteBGPriorityRank(gBattleAnimAttacker);
              spriteId = GetAnimBattlerSpriteId(ANIM_ATTACKER);
          }
          else
          {
              priorityRank = GetBattlerSpriteBGPriorityRank(gBattleAnimTarget);
              spriteId = GetAnimBattlerSpriteId(ANIM_TARGET);
          }
          if (spriteId != SPRITE_NONE)
          {
              gSprites[spriteId].invisible = FALSE;
              if (priorityRank == 2)
                  gSprites[spriteId].oam.priority = 3;

              if (priorityRank == 1)
                  ResetBattleAnimBg(FALSE);
              else
                  ResetBattleAnimBg(TRUE);
          }
      }
}

/** static void Cmd_teamattack_movefwd(void) */
export function Cmd_teamattack_movefwd(): any {
  let wantedBattler: any = null;
      let priorityRank: any = null;
      let spriteId: any = null;

      wantedBattler = sBattleAnimScriptPtr[1];
      sBattleAnimScriptPtr += 2;

       
      if (!IsContest() && IsDoubleBattle()
       && GetBattlerSide(gBattleAnimAttacker) == GetBattlerSide(gBattleAnimTarget))
      {
          if (wantedBattler == ANIM_ATTACKER)
          {
              priorityRank = GetBattlerSpriteBGPriorityRank(gBattleAnimAttacker);
              spriteId = GetAnimBattlerSpriteId(ANIM_ATTACKER);
          }
          else
          {
              priorityRank = GetBattlerSpriteBGPriorityRank(gBattleAnimTarget);
              spriteId = GetAnimBattlerSpriteId(ANIM_TARGET);
          }

          if (spriteId != SPRITE_NONE && priorityRank == 2)
              gSprites[spriteId].oam.priority = 2;
      }
}

/** static void Cmd_stopsound(void) */
export function Cmd_stopsound(): any {
  m4aMPlayStop(gMPlayInfo_SE1);
      m4aMPlayStop(gMPlayInfo_SE2);
      sBattleAnimScriptPtr++;
}

